package com.lianxibu.site.repository.jobs;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class ProcessApiRuntimeTelemetryTest {
 static final Instant START=Instant.parse("2026-01-01T00:05:00Z");static final String EPOCH="00000000-0000-4000-8000-000000000001";
 static final class Fixture{final AtomicReference<Instant> at=new AtomicReference<>(START);final AtomicLong nanos=new AtomicLong();final ProcessApiRuntimeTelemetry probe=new ProcessApiRuntimeTelemetry(new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return at.get();}},nanos::get,START.minusSeconds(300),EPOCH);void advance(long seconds){at.set(at.get().plusSeconds(seconds));nanos.addAndGet(Math.multiplyExact(seconds,1000000000L));}}
 @Test void onlyActuallyEnabledCompleteWindowHasNativeZeroAndPartialCaptureRemainsUnknown(){var f=new Fixture();assertNull(f.probe.read());try(var capture=f.probe.openCapture()){assertEquals("NativeApiCapture[redacted]",capture.toString());assertThrows(IllegalStateException.class,f.probe::openCapture);assertNull(f.probe.read());f.advance(299);assertNull(f.probe.read());f.advance(1);var full=f.probe.read();assertNotNull(full);assertEquals(0,full.requests());assertEquals(0,full.lockWaitP95Nanos());assertEquals(START,full.windowStart());}assertNull(f.probe.read());var partial=new Fixture();partial.advance(1);try(var capture=partial.probe.openCapture()){partial.advance(299);assertNull(partial.probe.read());partial.advance(300);assertNotNull(partial.probe.read());}}
 @Test void actualStatusesAndExactNearestRankP95BelongToTheirCompletedOriginalWindow(){var f=new Fixture();try(var capture=f.probe.openCapture()){for(int n=1;n<=20;n++){f.probe.completedHttp(n==20?503:200);f.probe.completedLockWait(n*1000000L);}f.advance(300);var actual=f.probe.read();assertEquals(20,actual.requests());assertEquals(1,actual.serverErrors());assertEquals(20,actual.lockSamples());assertEquals(19000000,actual.lockWaitP95Nanos());f.probe.completedHttp(500);f.probe.completedLockWait(100000001);assertEquals(actual,f.probe.read());f.advance(300);var next=f.probe.read();assertEquals(1,next.requests());assertEquals(1,next.serverErrors());assertEquals(100000001,next.lockWaitP95Nanos());assertEquals(actual.windowEnd(),next.windowStart());}}
 @Test void invalidEventAndHistogramOverflowPoisonOnlyActualWindowNeverInventingZero(){for(boolean histogram:new boolean[]{false,true}){var f=new Fixture();try(var capture=f.probe.openCapture()){if(histogram)for(long n=0;n<=65536;n++)f.probe.completedLockWait(n);else f.probe.completedHttp(600);f.advance(300);assertNull(f.probe.read());f.advance(300);assertNotNull(f.probe.read());}}var f=new Fixture();try(var capture=f.probe.openCapture()){f.probe.completedLockWait(-1);f.advance(300);assertNull(f.probe.read());}}
 @Test void rollbackClockJumpAndStaleCaptureCannotMakeKnownCurrentWindow(){var f=new Fixture();var old=f.probe.openCapture();f.at.set(START.minusSeconds(1));assertNull(f.probe.read());old.close();f.at.set(START);var current=f.probe.openCapture();old.close();f.advance(300);assertNotNull(f.probe.read());current.close();assertNull(f.probe.read());var jump=new Fixture();try(var capture=jump.probe.openCapture()){jump.at.set(START.plusSeconds(300));assertNull(jump.probe.read());jump.nanos.set(300000000000L);assertNull(jump.probe.read());}}
 @Test void actualConcurrentCompletionsDoNotLoseCountsAndNoEventContentsAreRecorded()throws Exception{var f=new Fixture();try(var capture=f.probe.openCapture()){var pool=Executors.newFixedThreadPool(4);try{var tasks=new java.util.ArrayList<Future<?>>();for(int thread=0;thread<4;thread++)tasks.add(pool.submit(()->{for(int n=0;n<1000;n++){f.probe.completedHttp(200);f.probe.completedLockWait(1000000);}}));for(var task:tasks)task.get(5,TimeUnit.SECONDS);}finally{pool.shutdownNow();}f.advance(300);var actual=f.probe.read();assertEquals(4000,actual.requests());assertEquals(4000,actual.lockSamples());assertEquals(1000000,actual.lockWaitP95Nanos());assertEquals("ProcessApiRuntimeTelemetry[redacted]",f.probe.toString());}}
}
